#!/usr/bin/env node
'use strict';

/**
 * Slack Web API caller for agent workflows.
 *
 * Usage:
 *   node slack_api.cjs <method> [jsonArgs] [--paginate]
 *
 * Examples:
 *   node slack_api.cjs auth.test
 *   node slack_api.cjs chat.postMessage '{"channel":"#general","text":"Hello from an agent"}'
 *   node slack_api.cjs conversations.history '{"channel":"C12345678","limit":10}'
 *   node slack_api.cjs conversations.list '{"types":"public_channel,private_channel","limit":200}' --paginate
 *
 * Environment:
 *   SLACK_TOKEN   Slack bot (xoxb-...) or user (xoxp-...) token.
 *   SLACK_API_URL Override API base URL (default https://slack.com/api). Used for tests.
 *
 * Behavior:
 *   - POSTs a JSON body to https://slack.com/api/<method> with Bearer auth.
 *   - Retries HTTP 429 up to 3 times, honoring the Retry-After header.
 *   - With --paginate, follows response_metadata.next_cursor and merges array
 *     fields across pages, capped at 500 items per collection (truncated: true).
 *   - Prints one JSON object to stdout and exits 0 on success, 1 on failure.
 */

const API_URL = (process.env.SLACK_API_URL || 'https://slack.com/api').replace(/\/+$/, '');
const TOKEN = process.env.SLACK_TOKEN || '';
const MAX_PAGES = 20;
const MAX_ITEMS_PER_COLLECTION = 500;

function fail(message, extra) {
  process.stdout.write(JSON.stringify({ ok: false, error: message, ...extra }));
  process.stdout.write('\n');
  process.exit(1);
}

async function main() {
  const rawArgs = process.argv.slice(2);
  const positional = rawArgs.filter((a) => !a.startsWith('--'));
  const flags = new Set(rawArgs.filter((a) => a.startsWith('--')));
  const method = positional[0];
  const jsonArg = positional[1];

  if (!method) {
    fail('Usage: node slack_api.cjs <method> [jsonArgs] [--paginate]', { usage: true });
  }
  if (!TOKEN) {
    fail('SLACK_TOKEN environment variable is required (bot token xoxb-... or user token xoxp-...)');
  }
  if (typeof fetch !== 'function') {
    fail('Node.js 18+ is required (global fetch is missing)');
  }

  let payload = {};
  if (jsonArg !== undefined) {
    try {
      payload = JSON.parse(jsonArg);
    } catch {
      fail('Arguments must be valid JSON, e.g. \'{"channel":"#general","text":"Hi"}\'', {
        badArgs: jsonArg,
      });
    }
    if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) {
      fail('Arguments JSON must be an object');
    }
  }

  const paginate = flags.has('--paginate');

  async function call(methodName, body, retriesLeft) {
    let res;
    try {
      res = await fetch(`${API_URL}/${methodName}`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${TOKEN}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
    } catch (err) {
      return { httpError: err.message };
    }

    if (res.status === 429 && retriesLeft > 0) {
      const retryAfterMs = Math.max(0, Number(res.headers.get('retry-after') || 1)) * 1000;
      await new Promise((r) => setTimeout(r, retryAfterMs));
      return call(methodName, body, retriesLeft - 1);
    }

    let data;
    try {
      data = await res.json();
    } catch {
      return { status: res.status, httpError: `HTTP ${res.status}: non-JSON response` };
    }
    return { status: res.status, data };
  }

  const first = await call(method, payload, 3);
  if (first.httpError) {
    fail(first.httpError, { method });
  }
  if (!first.data.ok) {
    const { ok, ...rest } = first.data;
    fail(rest.error || `HTTP ${first.status}`, { method, details: rest });
  }

  if (!paginate || !first.data.response_metadata || !first.data.response_metadata.next_cursor) {
    process.stdout.write(JSON.stringify({ ok: true, method, ...first.data }));
    process.stdout.write('\n');
    return;
  }

  const collectionKeys = Object.keys(first.data).filter((k) => Array.isArray(first.data[k]));
  if (collectionKeys.length === 0) {
    process.stdout.write(JSON.stringify({ ok: true, method, ...first.data }));
    process.stdout.write('\n');
    return;
  }

  const merged = {};
  for (const key of collectionKeys) merged[key] = [...first.data[key]];
  let cursor = first.data.response_metadata.next_cursor;
  let pages = 1;
  let truncated = false;

  while (cursor && pages < MAX_PAGES) {
    const next = await call(method, { ...payload, cursor }, 3);
    if (next.httpError) fail(next.httpError, { method });
    if (!next.data.ok) {
      const { ok, ...rest } = next.data;
      fail(rest.error || 'unknown error', { method, details: rest });
    }
    pages += 1;
    for (const key of collectionKeys) {
      merged[key].push(...(next.data[key] || []));
      if (merged[key].length > MAX_ITEMS_PER_COLLECTION) {
        merged[key] = merged[key].slice(0, MAX_ITEMS_PER_COLLECTION);
        truncated = true;
      }
    }
    if (truncated) break;
    cursor = (next.data.response_metadata && next.data.response_metadata.next_cursor) || '';
  }

  process.stdout.write(JSON.stringify({ ok: true, method, pages, truncated, ...merged }));
  process.stdout.write('\n');
}

main().catch((err) => fail(err.message));

#!/usr/bin/env node
'use strict';

/**
 * Task-local test harness for slack-api/scripts/slack_api.cjs.
 * Runs a mock Slack Web API server locally and asserts script behavior:
 * success envelope, parameter validation, pagination merge, truncation cap,
 * 429 retry, Slack error envelope, missing token, and invalid JSON args.
 */

const http = require('node:http');
const { spawn } = require('node:child_process');
const path = require('node:path');
const assert = require('node:assert');

const SCRIPT = path.join(__dirname, 'slack-api', 'scripts', 'slack_api.cjs');
const BASE_TOKEN = 'xoxb-test';

let flakyCalls = 0;

function json(res, code, body) {
  res.writeHead(code, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(body));
}

const server = http.createServer((req, res) => {
  let raw = '';
  req.on('data', (c) => (raw += c));
  req.on('end', () => {
    let body = {};
    try {
      body = raw ? JSON.parse(raw) : {};
    } catch {
      /* keep {} */
    }
    const method = req.url.slice(1);
    if ((req.headers.authorization || '') !== `Bearer ${BASE_TOKEN}`) {
      return json(res, 200, { ok: false, error: 'invalid_auth' });
    }

    switch (method) {
      case 'auth.test':
        return json(res, 200, {
          ok: true,
          url: 'https://mock.slack.com/',
          team: 'Mock Team',
          user: 'agent',
          team_id: 'T1',
          user_id: 'U1',
        });

      case 'chat.postMessage':
        if (!body.channel || !body.text) {
          return json(res, 200, { ok: false, error: 'invalid_arguments' });
        }
        return json(res, 200, {
          ok: true,
          channel: body.channel,
          ts: '1234567890.000100',
          message: { type: 'message', text: body.text },
        });

      case 'conversations.history':
        if (!body.cursor) {
          return json(res, 200, {
            ok: true,
            messages: [
              { ts: '1.1', text: 'first' },
              { ts: '1.2', text: 'second' },
            ],
            has_more: true,
            response_metadata: { next_cursor: 'c2' },
          });
        }
        return json(res, 200, {
          ok: true,
          messages: [{ ts: '2.1', text: 'third' }],
          has_more: false,
        });

      case 'conversations.list': {
        const channels = Array.from({ length: 300 }, (_, i) => ({
          id: `C${i}`,
          name: `chan-${i}`,
        }));
        return json(res, 200, {
          ok: true,
          channels,
          response_metadata: { next_cursor: 'c2' },
        });
      }

      case 'flaky.method':
        flakyCalls += 1;
        if (flakyCalls === 1) {
          res.writeHead(429, {
            'Content-Type': 'application/json',
            'Retry-After': '0',
          });
          res.end('{"ok":false,"error":"rate_limited"}');
          return;
        }
        return json(res, 200, { ok: true, recovered: true });

      case 'bad.method':
        return json(res, 200, {
          ok: false,
          error: 'missing_scope',
          needed: 'channels:read',
          provided: 'chat:write',
        });

      default:
        return json(res, 200, { ok: false, error: 'method_not_found' });
    }
  });
});

function run(args, env) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [SCRIPT, ...args], {
      env: {
        ...process.env,
        SLACK_API_URL: `http://127.0.0.1:${server.address().port}`,
        SLACK_TOKEN: BASE_TOKEN,
        ...(env || {}),
      },
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => (stdout += d));
    child.stderr.on('data', (d) => (stderr += d));
    child.on('close', (code) => resolve({ code, stdout, stderr }));
  });
}

const results = [];
function check(name, cond, detail) {
  results.push({ name, pass: Boolean(cond), detail: detail || '' });
}

async function main() {
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const port = server.address().port;
  console.log(`Mock Slack API listening on 127.0.0.1:${port}`);
  console.log(`Testing script: ${SCRIPT}\n`);

  try {
    // 1. Basic success envelope
    let r = await run(['auth.test']);
    let out = JSON.parse(r.stdout);
    check('auth.test succeeds', r.code === 0 && out.ok === true && out.method === 'auth.test', r.stdout.trim());

    // 2. postMessage with args, plus server-side param validation
    r = await run(['chat.postMessage', '{"channel":"#general","text":"Hello"}']);
    out = JSON.parse(r.stdout);
    check('chat.postMessage returns ts', r.code === 0 && out.ok === true && out.ts === '1234567890.000100', r.stdout.trim());
    r = await run(['chat.postMessage', '{"channel":"#general"}']);
    out = JSON.parse(r.stdout);
    check('server invalid_arguments surfaces as failure', r.code === 1 && out.ok === false && out.error === 'invalid_arguments', r.stdout.trim());

    // 3. No pagination flag: single page only
    r = await run(['conversations.history', '{"channel":"C1","limit":10}']);
    out = JSON.parse(r.stdout);
    check('history without --paginate returns 2 messages', r.code === 0 && out.messages.length === 2, r.stdout.trim());

    // 4. Pagination merge
    r = await run(['conversations.history', '{"channel":"C1","limit":10}', '--paginate']);
    out = JSON.parse(r.stdout);
    check(
      'history --paginate merges 3 messages over 2 pages',
      r.code === 0 && out.messages.length === 3 && out.pages === 2 && out.truncated === false,
      r.stdout.trim(),
    );

    // 5. Truncation cap at 500 items
    r = await run(['conversations.list', '{"limit":200}', '--paginate']);
    out = JSON.parse(r.stdout);
    check(
      'conversations.list --paginate caps at 500 and flags truncated',
      r.code === 0 && out.channels.length === 500 && out.truncated === true,
      r.stdout.trim(),
    );

    // 6. 429 retry
    r = await run(['flaky.method']);
    out = JSON.parse(r.stdout);
    check('429 is retried and succeeds', r.code === 0 && out.ok === true && out.recovered === true && flakyCalls === 2, r.stdout.trim());

    // 7. Slack error envelope with details
    r = await run(['bad.method']);
    out = JSON.parse(r.stdout);
    check(
      'Slack error envelope surfaces error and details',
      r.code === 1 && out.ok === false && out.error === 'missing_scope' && out.details && out.details.needed === 'channels:read',
      r.stdout.trim(),
    );

    // 8. Unknown method
    r = await run(['nope.method']);
    out = JSON.parse(r.stdout);
    check('unknown method fails cleanly', r.code === 1 && out.ok === false && out.error === 'method_not_found', r.stdout.trim());

    // 9. Missing token
    r = await run(['auth.test'], { SLACK_TOKEN: '' });
    out = JSON.parse(r.stdout);
    check('missing token produces clear error', r.code === 1 && /SLACK_TOKEN/.test(out.error), r.stdout.trim());

    // 10. Invalid JSON args
    r = await run(['chat.postMessage', '{not json']);
    out = JSON.parse(r.stdout);
    check('invalid JSON args produce clear error', r.code === 1 && /valid JSON/.test(out.error), r.stdout.trim());
  } catch (err) {
    results.push({ name: 'harness', pass: false, detail: err.message });
  } finally {
    server.close();
  }

  let failed = 0;
  console.log('--- Results ---');
  for (const res of results) {
    if (!res.pass) failed += 1;
    console.log(`${res.pass ? 'PASS' : 'FAIL'}  ${res.name}${res.detail ? `  (${res.detail})` : ''}`);
  }
  console.log(`\n${results.length - failed}/${results.length} checks passed`);
  process.exit(failed === 0 ? 0 : 1);
}

main();

#!/usr/bin/env node
'use strict';

/**
 * Task-local packager replicating skill-creator's package_skill.cjs:
 * validates the skill (same rules as validate_skill.cjs) and zips the
 * skill folder contents into <skill-name>.skill (a zip archive).
 * Uses a pure-Node store-only zip writer so no system tools are needed.
 *
 * Usage:
 *   node package_slack_skill.cjs <skill-folder> [output-directory]
 */

const fs = require('node:fs');
const path = require('node:path');

// ---------- validation (mirrors skill-creator's validate_skill.cjs) ----------

function getAllFiles(dir, fileList = []) {
  for (const file of fs.readdirSync(dir)) {
    const name = path.join(dir, file);
    if (fs.statSync(name).isDirectory()) {
      if (!['node_modules', '.git', '__pycache__'].includes(file)) getAllFiles(name, fileList);
    } else {
      fileList.push(name);
    }
  }
  return fileList;
}

function validateSkill(skillPath) {
  if (!fs.existsSync(skillPath) || !fs.statSync(skillPath).isDirectory()) {
    return { valid: false, message: `Path is not a directory: ${skillPath}` };
  }
  const skillMdPath = path.join(skillPath, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) return { valid: false, message: 'SKILL.md not found' };

  const content = fs.readFileSync(skillMdPath, 'utf8');
  if (!content.startsWith('---')) return { valid: false, message: 'No YAML frontmatter found' };
  const parts = content.split('---');
  if (parts.length < 3) return { valid: false, message: 'Invalid frontmatter format' };

  const frontmatterText = parts[1];
  const nameMatch = frontmatterText.match(/^name:\s*(.+)$/m);
  const descMatch = frontmatterText.match(/^description:\s*(?:'([^']*)'|"([^"]*)"|(.+))$/m);
  if (!nameMatch) return { valid: false, message: 'Missing "name" in frontmatter' };
  if (!descMatch) return { valid: false, message: 'Description must be a single-line string: description: ...' };

  const name = nameMatch[1].trim();
  const description = (descMatch[1] !== undefined ? descMatch[1] : descMatch[2] !== undefined ? descMatch[2] : descMatch[3] || '').trim();
  if (description.includes('\n')) return { valid: false, message: 'Description must be a single line (no newlines)' };
  if (!/^[a-z0-9-]+$/.test(name)) return { valid: false, message: `Name "${name}" should be hyphen-case` };
  if (description.length > 1024) return { valid: false, message: 'Description is too long (max 1024)' };

  for (const file of getAllFiles(skillPath)) {
    if (fs.readFileSync(file, 'utf8').includes('TODO:')) {
      return { valid: true, message: 'Skill has unresolved TODOs', warning: `Found unresolved TODO in ${path.relative(skillPath, file)}` };
    }
  }
  return { valid: true, message: 'Skill is valid!' };
}

// ---------- minimal store-only zip writer ----------

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c;
  }
  return table;
})();

function crc32(buf) {
  let crc = -1;
  for (let i = 0; i < buf.length; i++) crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ buf[i]) & 0xff];
  return (crc ^ -1) >>> 0;
}

function dosDateTime(d) {
  return {
    time: (d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1),
    date: (((d.getFullYear() - 1980) & 0x7f) << 9) | ((d.getMonth() + 1) << 5) | d.getDate(),
  };
}

function buildZip(entries) {
  // entries: [{ name, data (Buffer), mode (unix perms), isDir }]
  const localParts = [];
  const centralParts = [];
  let offset = 0;
  const now = dosDateTime(new Date());

  for (const entry of entries) {
    const nameBuf = Buffer.from(entry.name, 'utf8');
    const crc = crc32(entry.data);
    const size = entry.data.length;
    const externalAttr = (entry.isDir ? 0x10 : 0) | ((entry.mode & 0xffff) << 16);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0);
    local.writeUInt16LE(20, 4); // version needed
    local.writeUInt16LE(0x0800, 6); // UTF-8 names
    local.writeUInt16LE(0, 8); // store
    local.writeUInt16LE(now.time, 10);
    local.writeUInt16LE(now.date, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(size, 18);
    local.writeUInt32LE(size, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28); // extra length
    localParts.push(local, nameBuf, entry.data);

    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50, 0);
    central.writeUInt16LE(0x0314, 4); // made by: unix, 2.0
    central.writeUInt16LE(20, 6); // version needed
    central.writeUInt16LE(0x0800, 8);
    central.writeUInt16LE(0, 10); // store
    central.writeUInt16LE(now.time, 12);
    central.writeUInt16LE(now.date, 14);
    central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(size, 20);
    central.writeUInt32LE(size, 24);
    central.writeUInt16LE(nameBuf.length, 28);
    central.writeUInt16LE(0, 30); // extra
    central.writeUInt16LE(0, 32); // comment
    central.writeUInt16LE(0, 34); // disk
    central.writeUInt16LE(0, 36); // internal attrs
    central.writeUInt32LE(externalAttr >>> 0, 38);
    central.writeUInt32LE(offset, 42);
    centralParts.push(central, nameBuf);

    offset += 30 + nameBuf.length + size;
  }

  const centralBuf = Buffer.concat(centralParts);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(centralBuf.length, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);

  return Buffer.concat([...localParts, centralBuf, eocd]);
}

// ---------- main ----------

function main() {
  const args = process.argv.slice(2);
  const skillPathArg = args[0] || 'slack-api';
  const outputDirArg = args[1] || process.cwd();
  if (skillPathArg.includes('..') || outputDirArg.includes('..')) {
    console.error('❌ Error: Path traversal detected in arguments.');
    process.exit(1);
  }

  const skillPath = path.resolve(skillPathArg);
  const outputDir = path.resolve(outputDirArg);
  const skillName = path.basename(skillPath);

  console.log('🔍 Validating skill...');
  const result = validateSkill(skillPath);
  if (!result.valid) {
    console.error(`❌ Validation failed: ${result.message}`);
    process.exit(1);
  }
  if (result.warning) {
    console.warn(`⚠️  ${result.warning}`);
    console.log('Please resolve all TODOs before packaging.');
    process.exit(1);
  }
  console.log('✅ Skill is valid!');

  const files = getAllFiles(skillPath);
  const entries = [];
  const rel = (p) => path.relative(skillPath, p).split(path.sep).join('/');

  // directory entries first (mirrors `zip -r` structure)
  const dirs = new Set();
  for (const f of files) {
    let d = path.dirname(rel(f));
    while (d !== '.') {
      dirs.add(d);
      d = path.dirname(d);
    }
  }
