#!/usr/bin/env node
'use strict';

/**
 * Slack Web API caller for agent workflows.
 *
 * Usage:
 *   node slack_api.cjs <method> [jsonArgs] [--paginate]
 *
 * Examples:
 *   node slack_api.cjs auth.test
 *   node slack_api.cjs chat.postMessage '{"channel":"#general","text":"Hello from an agent"}'
 *   node slack_api.cjs conversations.history '{"channel":"C12345678","limit":10}'
 *   node slack_api.cjs conversations.list '{"types":"public_channel,private_channel","limit":200}' --paginate
 *
 * Environment:
 *   SLACK_TOKEN   Slack bot (xoxb-...) or user (xoxp-...) token.
 *   SLACK_API_URL Override API base URL (default https://slack.com/api). Used for tests.
 *
 * Behavior:
 *   - POSTs a JSON body to https://slack.com/api/<method> with Bearer auth.
 *   - Retries HTTP 429 up to 3 times, honoring the Retry-After header.
 *   - With --paginate, follows response_metadata.next_cursor and merges array
 *     fields across pages, capped at 500 items per collection (truncated: true).
 *   - Prints one JSON object to stdout and exits 0 on success, 1 on failure.
 */

const API_URL = (process.env.SLACK_API_URL || 'https://slack.com/api').replace(/\/+$/, '');
const TOKEN = process.env.SLACK_TOKEN || '';
const MAX_PAGES = 20;
const MAX_ITEMS_PER_COLLECTION = 500;

function fail(message, extra) {
  process.stdout.write(JSON.stringify({ ok: false, error: message, ...extra }));
  process.stdout.write('\n');
  process.exit(1);
}

async function main() {
  const rawArgs = process.argv.slice(2);
  const positional = rawArgs.filter((a) => !a.startsWith('--'));
  const flags = new Set(rawArgs.filter((a) => a.startsWith('--')));
  const method = positional[0];
  const jsonArg = positional[1];

  if (!method) {
    fail('Usage: node slack_api.cjs <method> [jsonArgs] [--paginate]', { usage: true });
  }
  if (!TOKEN) {
    fail('SLACK_TOKEN environment variable is required (bot token xoxb-... or user token xoxp-...)');
  }
  if (typeof fetch !== 'function') {
    fail('Node.js 18+ is required (global fetch is missing)');
  }

  let payload = {};
  if (jsonArg !== undefined) {
    try {
      payload = JSON.parse(jsonArg);
    } catch {
      fail('Arguments must be valid JSON, e.g. \'{"channel":"#general","text":"Hi"}\'', {
        badArgs: jsonArg,
      });
    }
    if (payload === null || typeof payload !== 'object' || Array.isArray(payload)) {
      fail('Arguments JSON must be an object');
    }
  }

  const paginate = flags.has('--paginate');

  async function call(methodName, body, retriesLeft) {
    let res;
    try {
      res = await fetch(`${API_URL}/${methodName}`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${TOKEN}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
    } catch (err) {
      return { httpError: err.message };
    }

    if (res.status === 429 && retriesLeft > 0) {
      const retryAfterMs = Math.max(0, Number(res.headers.get('retry-after') || 1)) * 1000;
      await new Promise((r) => setTimeout(r, retryAfterMs));
      return call(methodName, body, retriesLeft - 1);
    }

    let data;
    try {
      data = await res.json();
    } catch {
      return { status: res.status, httpError: `HTTP ${res.status}: non-JSON response` };
    }
    return { status: res.status, data };
  }

  const first = await call(method, payload, 3);
  if (first.httpError) {
    fail(first.httpError, { method });
  }
  if (!first.data.ok) {
    const { ok, ...rest } = first.data;
    fail(rest.error || `HTTP ${first.status}`, { method, details: rest });
  }

  if (!paginate || !first.data.response_metadata || !first.data.response_metadata.next_cursor) {
    process.stdout.write(JSON.stringify({ ok: true, method, ...first.data }));
    process.stdout.write('\n');
    return;
  }

  const collectionKeys = Object.keys(first.data).filter((k) => Array.isArray(first.data[k]));
  if (collectionKeys.length === 0) {
    process.stdout.write(JSON.stringify({ ok: true, method, ...first.data }));
    process.stdout.write('\n');
    return;
  }

  const merged = {};
  for (const key of collectionKeys) merged[key] = [...first.data[key]];
  let cursor = first.data.response_metadata.next_cursor;
  let pages = 1;
  let truncated = false;

  while (cursor && pages < MAX_PAGES) {
    const next = await call(method, { ...payload, cursor }, 3);
    if (next.httpError) fail(next.httpError, { method });
    if (!next.data.ok) {
      const { ok, ...rest } = next.data;
      fail(rest.error || 'unknown error', { method, details: rest });
    }
    pages += 1;
    for (const key of collectionKeys) {
      merged[key].push(...(next.data[key] || []));
      if (merged[key].length > MAX_ITEMS_PER_COLLECTION) {
        merged[key] = merged[key].slice(0, MAX_ITEMS_PER_COLLECTION);
        truncated = true;
      }
    }
    if (truncated) break;
    cursor = (next.data.response_metadata && next.data.response_metadata.next_cursor) || '';
  }

  process.stdout.write(JSON.stringify({ ok: true, method, pages, truncated, ...merged }));
  process.stdout.write('\n');
}

main().catch((err) => fail(err.message));

#!/usr/bin/env node
'use strict';

/**
 * Regression tests for scripts/slack_api.cjs.
 *
 * Starts a local mock Slack API server (via the SLACK_API_URL override),
 * spawns slack_api.cjs as a child process for each scenario, and asserts on
 * the JSON it prints to stdout. Exits 0 when every check passes, 1 otherwise.
 *
 * Usage: node scripts/test_slack_api.cjs
 */

const { spawn } = require('node:child_process');
const http = require('node:http');
const path = require('node:path');

const SCRIPT = path.join(__dirname, 'scripts', 'slack_api.cjs');
const TOKEN = 'xoxb-test';

const results = [];
let baseUrl = '';
let server;

let rateCalls = 0;
let listCalls = 0;

const routes = {
  'auth.test': () => ({
    ok: true,
    url: 'https://example.slack.com/',
    team: 'Test Workspace',
    user: 'testbot',
    team_id: 'T1',
    user_id: 'U1',
  }),
  'chat.postMessage': (_req, body) => {
    if (!body.channel) return { ok: false, error: 'invalid_arguments' };
    return {
      ok: true,
      channel: body.channel,
      ts: '1234567890.123456',
      message: { text: body.text || '', ts: '1234567890.123456' },
    };
  },
  'echo.test': (_req, body) => ({ ok: true, received: body }),
  'conversations.list': (_req, body) => {
    listCalls += 1;
    if (!body.cursor) {
      return {
        ok: true,
        channels: [
          { id: 'C1', name: 'general' },
          { id: 'C2', name: 'random' },
        ],
        response_metadata: { next_cursor: 'cursor-2' },
      };
    }
    return {
      ok: true,
      channels: [{ id: 'C3', name: 'third' }],
      response_metadata: { next_cursor: '' },
    };
  },
  'rate.test': () => {
    rateCalls += 1;
    if (rateCalls === 1) {
      return {
        status: 429,
        headers: { 'Retry-After': '0' },
        body: { ok: false, error: 'rate_limited' },
      };
    }
    return { ok: true, attempts: rateCalls };
  },
  'fail.test': () => ({ ok: false, error: 'missing_scope', needed: 'chat:write', provided: 'chat:read' }),
};

function startServer() {
  return new Promise((resolve, reject) => {
    const srv = http.createServer((req, res) => {
      let raw = '';
      req.on('data', (chunk) => { raw += chunk; });
      req.on('end', () => {
        let body = {};
        try {
          body = raw ? JSON.parse(raw) : {};
        } catch {
          body = {};
        }
        const method = String(req.url || '').split('?')[0].replace(/^\/+/, '');
        const send = (status, obj, headers = {}) => {
          res.writeHead(status, { 'Content-Type': 'application/json', ...headers });
          res.end(JSON.stringify(obj));
        };
        if (req.headers.authorization !== `Bearer ${TOKEN}`) {
          send(200, { ok: false, error: 'invalid_auth' });
          return;
        }
        const handler = routes[method];
        if (!handler) {
          send(404, { ok: false, error: 'method_not_found' });
          return;
        }
        const result = handler(req, body);
        if (result && result.status === 429) {
          send(429, result.body, result.headers);
          return;
        }
        send(200, result);
      });
    });
    srv.on('error', reject);
    srv.listen(0, '127.0.0.1', () => {
      baseUrl = `http://127.0.0.1:${srv.address().port}`;
      resolve(srv);
    });
  });
}

function runScript(args, envOverrides = {}) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [SCRIPT, ...args], {
      env: {
        ...process.env,
        SLACK_TOKEN: TOKEN,
        SLACK_API_URL: baseUrl,
        ...envOverrides,
      },
      stdio: ['ignore', 'pipe', 'pipe'],
    });
    let stdout = '';
    let stderr = '';
    child.stdout.on('data', (d) => { stdout += d; });
    child.stderr.on('data', (d) => { stderr += d; });
    const timer = setTimeout(() => child.kill('SIGKILL'), 20000);
    child.on('close', (code) => {
      clearTimeout(timer);
      resolve({ code, stdout, stderr });
    });
  });
}

function check(name, pass, detail) {
  results.push(pass);
  console.log(`${pass ? 'PASS' : 'FAIL'} ${name}${pass ? '' : ` -- ${detail}`}`);
}

function parse(out) {
  try {
    return JSON.parse(out.stdout.trim());
  } catch {
    return null;
  }
}

async function main() {
  server = await startServer();
  let out;
  let json;

  out = await runScript([]);
  check(
    'missing method prints usage and exits 1',
    out.code === 1 && /Usage/.test(out.stdout) && out.stdout.includes('"ok":false'),
    out.stdout.trim(),
  );

  out = await runScript(['auth.test']);
  json = parse(out);
  check(
    'auth.test succeeds with token identity',
    out.code === 0 && json && json.ok === true && json.user_id === 'U1',
    out.stdout.trim(),
  );

  out = await runScript(['chat.postMessage', '{"channel":"C1","text":"hi"}']);
  json = parse(out);
  check(
    'chat.postMessage sends args and echoes channel',
    out.code === 0 && json && json.ok === true && json.channel === 'C1' && json.message.text === 'hi',
    out.stdout.trim(),
  );

  out = await runScript(['echo.test', '{"a":1,"b":"x"}']);
  json = parse(out);
  check(
    'JSON args forwarded verbatim as request body',
    out.code === 0 && json && json.ok === true && json.received && json.received.a === 1 && json.received.b === 'x',
    out.stdout.trim(),
  );

  out = await runScript(['chat.postMessage', '{not json']);
  check(
    'invalid JSON args fail with exit 1',
    out.code === 1 && /valid JSON/.test(out.stdout),
    out.stdout.trim(),
  );

  out = await runScript(['conversations.list', '{"limit":2}', '--paginate']);
  json = parse(out);
  check(
    '--paginate follows next_cursor and merges pages',
    out.code === 0 && json && json.ok === true && json.pages === 2 &&
      Array.isArray(json.channels) && json.channels.length === 3 &&
      json.channels[2].id === 'C3' && listCalls === 2,
    out.stdout.trim(),
  );

  out = await runScript(['rate.test']);
  json = parse(out);
  check(
    'HTTP 429 is retried honoring Retry-After',
    out.code === 0 && json && json.ok === true && json.attempts === 2 && rateCalls === 2,
    out.stdout.trim(),
  );

  out = await runScript(['fail.test']);
  json = parse(out);
  check(
    'API error surfaces ok:false with error code and details',
    out.code === 1 && json && json.ok === false && json.error === 'missing_scope' &&
      json.details && json.details.needed === 'chat:write',
    out.stdout.trim(),
  );

  out = await runScript(['auth.test'], { SLACK_TOKEN: '' });
  check(
    'missing SLACK_TOKEN fails with exit 1',
    out.code === 1 && /SLACK_TOKEN/.test(out.stdout),
    out.stdout.trim(),
  );

  server.close();
  const failed = results.filter((p) => !p).length;
  console.log(`\n${results.length - failed}/${results.length} checks passed`);
  process.exit(failed ? 1 : 0);
}

main().catch((err) => {
  console.error('Test harness error:', err);
  if (server) server.close();
  process.exit(1);
});
